head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getFormattedHeaderValue]<br/>Header Column 정보를 사용하여 특정 Column 의 포맷을 전달한 값에 적용하여 반환합니다.",
    "validation" : [
        "headerId(필수) 파라미터로 포맷 정보를 가져올 Header Column 의 ID 를 설정할 수 있어야 합니다.",
        "headerId 를 ID 로 설정할 경우 대소문자를 구분하지 않아야 합니다.",
    ]
}



// displayFormatter 로 사용할 scope 함수 (col2, col3 Header Column 에 설정)
scwin.fmtBracket = function (data) {
    return "[" + data + "]";
};



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="col1=displayFormat(####-##-##) / col2=displayFormatter([]) / col3=displayFormat+displayFormatter(displayFormatter 우선) / col4=포맷 미설정"', '', 'label1');

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (Header Column 4개, 포맷 속성 조합)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" dataType="text" id="col1" value="col1(format)" displayFormat="####-##-##"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" dataType="text" id="col2" value="col2(formatter)" displayFormatter="scwin.fmtBracket"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" dataType="text" id="col3" value="col3(both)" displayFormat="####-##-##" displayFormatter="scwin.fmtBracket"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" dataType="text" id="col4" value="col4(none)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



scwin.btn_getFormattedHeaderValue_onclick = function () {
    // headerId 는 ID(String) 그대로 전달 (Number 변환 금지)
    let headerId = par_headerId.getValue();
    let value = par_value.getValue();

    // Header Column 의 displayFormat / displayFormatter 를 value 에 적용한 결과 반환
    let rtn = target1.getFormattedHeaderValue(headerId, value);

    if (typeof rtn === 'undefined') {
        rtn = 'undefined';
    }

    wf_body_bottom.getObj("scwin").setReturnValue("getFormattedHeaderValue('" + headerId + "', '" + value + "') : " + rtn);
}
